package com.dukankhata.purchase;
import com.dukankhata.common.exception.*; import com.dukankhata.common.security.CurrentUserService; import com.dukankhata.product.*; import com.dukankhata.shop.*; import com.dukankhata.supplier.*; import com.dukankhata.purchase.dto.*; import com.dukankhata.inventory.InventoryService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;
@Service public class PurchaseService{
 private final PurchaseRepository purchases; private final ProductRepository products; private final SupplierRepository suppliers; private final CurrentUserService current; private final SupplierService supplierService; private final InventoryService inventory; private final ShopRepository shops;
 public PurchaseService(PurchaseRepository purchases,ProductRepository products,SupplierRepository suppliers,CurrentUserService current,SupplierService supplierService,InventoryService inventory,ShopRepository shops){this.purchases=purchases;this.products=products;this.suppliers=suppliers;this.current=current;this.supplierService=supplierService;this.inventory=inventory;this.shops=shops;}
 @Transactional public PurchaseResponse create(CreatePurchaseRequest r){UUID shopId=current.shopId();Shop shop=shops.findByIdForUpdate(shopId).orElseThrow(()->new ResourceNotFoundException("Shop not found"));Supplier supplier=suppliers.findByIdAndShopIdAndActiveTrue(r.supplierId(),shopId).orElseThrow(()->new ResourceNotFoundException("Supplier not found"));
  Purchase p=new Purchase();p.setShop(shop);p.setSupplier(supplier);p.setPurchaseNumber(nextNumber(shopId,LocalDate.now(ZoneId.of("Asia/Kolkata"))));p.setSupplierInvoiceNumber(trim(r.supplierInvoiceNumber()));p.setNote(trim(r.note()));BigDecimal subtotal=BigDecimal.ZERO;
  for(PurchaseItemRequest x:r.items()){Product product=products.findByIdAndShopIdAndActiveTrue(x.productId(),shopId).orElseThrow(()->new ResourceNotFoundException("Product not found"));BigDecimal q=x.quantity().setScale(3,RoundingMode.HALF_UP);BigDecimal cost=x.unitCost().setScale(2,RoundingMode.HALF_UP);BigDecimal line=cost.multiply(q).setScale(2,RoundingMode.HALF_UP);subtotal=subtotal.add(line);PurchaseItem i=new PurchaseItem();i.setPurchase(p);i.setProduct(product);i.setProductName(product.getName());i.setQuantity(q);i.setUnitCost(cost);i.setLineTotal(line);p.getItems().add(i);}
  BigDecimal total=subtotal.setScale(2,RoundingMode.HALF_UP);BigDecimal paid=r.paidAmount().setScale(2,RoundingMode.HALF_UP);if(paid.compareTo(total)>0)throw new BusinessException("Paid amount cannot exceed purchase total");BigDecimal payable=total.subtract(paid);p.setSubtotal(total);p.setTax(BigDecimal.ZERO);p.setTotal(total);p.setPaidAmount(paid);p.setPayableAmount(payable);p.setPaymentStatus(payable.signum()==0?PurchasePaymentStatus.PAID:(paid.signum()==0?PurchasePaymentStatus.CREDIT:PurchasePaymentStatus.PARTIAL));
  Purchase saved=purchases.save(p);
  for(PurchaseItem i:saved.getItems()) inventory.receivePurchase(i.getProduct(),i.getQuantity(),i.getUnitCost(),"Purchase "+saved.getPurchaseNumber());
  if(payable.signum()>0) supplierService.charge(supplier,payable,"Purchase "+saved.getPurchaseNumber());
  return PurchaseResponse.from(saved);
 }
 @Transactional(readOnly=true) public List<PurchaseResponse> list(){return purchases.findTop100ByShopIdOrderByCreatedAtDesc(current.shopId()).stream().map(PurchaseResponse::from).toList();}
 @Transactional(readOnly=true) public PurchaseResponse get(UUID id){return PurchaseResponse.from(purchases.findByIdAndShopId(id,current.shopId()).orElseThrow(()->new ResourceNotFoundException("Purchase not found")));}
 private String nextNumber(UUID shopId,LocalDate today){String prefix="PUR-"+today.format(DateTimeFormatter.BASIC_ISO_DATE)+"-";Integer maxSuffix=purchases.findMaxPurchaseSuffix(shopId,prefix,prefix.length()+1);return prefix+String.format("%04d",Math.addExact(maxSuffix==null?0:maxSuffix,1));}
 private String trim(String x){return x==null||x.isBlank()?null:x.trim();}
}
